/** A level belongs to the requesting conversation, not whichever sibling is
 * selected in the UI or the bot's default for future conversations. */
function sourceApprovalMode(botId: string, threadId: string): ApprovalMode {
  const owner = connectorThread(botId, threadId);
  if (!owner) return "ask";
  const bot = store.projectBotForTask(botId, threadId) ?? owner.bot;
  // Origin changes Custom to Auto, never Full; no live-turn state is needed.
  return approvalModeForTurn(bot, false, threadId);
}

/** #1905: the one Full access decision (full-access-gate.ts) for the level
 * the requesting conversation runs at: proposals, routine cards, team setup
 * and peer contact all read it here. */
function fullAccessForSource(botId: string, threadId: string): boolean {
  return fullAccessActs(sourceApprovalMode(botId, threadId));
}

/** On a Cloud home a turn a guest drives keeps a card for every change,
 * even one to the bot itself. */
function selfApplyBlocked(threadId: string): boolean {
  return cloudGuestDriven(threadId) || botmailConfined(threadId);
}

/** Whether a bot's routine, skill, profile or model change applies without
 * a person, and why: Full access applies everything as it always has, and
 * at any level a change to the bot itself applies, shown as a one-line
 * receipt with Undo (server/direct-apply.ts). Peer approvals stay Full
 * access only (fullAccessForSource); team setup follows teamSetupDirectSource. */

/** 2026-10-26: team setup, create_bot and a bot deletion apply without a
 * card at Full access, and at Approve for me on the person's own turn when
 * every bot they touch is theirs (team-setup-requests.ts teamSetupDirectApply). */

/** 2026-10-20 ("le bot principal fait tout"): a proposal the person's own
 * Primary Bot makes because the person asked for it in this turn's message
 * applies at once, without a card: the submit gets `primaryAsked`, passed
 * down explicitly (never a shared flag another call could read). */
/** The same proof as sagax_settings' quote (server/settings-actions.ts):
 * the person's own Primary Bot, their own message in this turn, the quote in
 * it with a word of the change, the target bot (or routine) named and the
 * person's own. The proof, or why not. */

/** Runs one submit with the person's request as its grant, and journals it
 * as theirs, via the Primary Bot. */
async function withPrimaryAsked<T>(proof: { botName: string; messageId: string; person: string; quote: string } | string, scope: { botId: string; threadId: string; targetBotId: string; kind: string }, submit: (primaryAsked: boolean) => T | Promise<T>): Promise<T> {
  if (typeof proof === "string") return submit(false);
  const result = await submit(true);
  if ((result as { state?: unknown } | null)?.state === "applied") appendAdminAction(DATA_DIR, {
    category: "setting", action: "setting.change", target: { kind: "bot", id: scope.targetBotId }, changed: [scope.kind],
    after: { how: "run", bot: scope.botId, via: "primary-bot", viaBot: proof.botName, messageId: proof.messageId, quote: proof.quote.slice(0, 200) },
    actor: IDENTITY.kind === "perspicax" ? { kind: "person", principalId: proof.person, via: "sagax" } : { kind: "loopback" }
  });
  return result;
}

/** A quote that did not prove the request, journaled so an injection
 * attempt is visible. */
function journalRefusedQuote(botId: string, targetBotId: string, kind: string, reason: string): void {
  appendAdminAction(DATA_DIR, { category: "setting", action: "setting.refused", target: { kind: "bot", id: targetBotId }, changed: [kind],
    after: { bot: botId, via: "primary-bot", reason: reason.slice(0, 200) }, actor: { kind: "loopback" } });
}

/** Ask before contacting bots: the Sagax peer card, below Full access only
 * (#1819, #1905: full-access-gate.ts peerContactCardRequired). */
function peerReviewRequired(bot: BotRecord, threadId: string): boolean {
  return peerContactCardRequired(Boolean(bot.approvePeerComms), sourceApprovalMode(bot.id, threadId));
}

/** A Primary Bot's level flows down its delegation. The person set the
 * Primary Bot's level so its work runs that way; a teammate the Primary Bot brings in
 * starting at "Ask for approval" meant switching every such thread by hand,
 * all day, for the whole team. So a teammate a Primary Bot delegates to starts at
 * the Primary Bot's level for that work: Auto-accept edits, Approve for me or Full
 * access (delegatedApprovalMode: never lower than the teammate's own level,
 * capped at what its engine implements). Only a Primary Bot passes its level on —
 * an ordinary bot's delegation still uses the recipient's setting. Returns
 * null to keep the recipient's own level. */
const delegatedLevel = createDelegatedLevel({
  store,
  node: (id) => coordinator.node(id),
  sourceLevel: sourceApprovalMode,
  turnLevel: approvalModeForTurn,
  driverKind: (bot) => registry.cliTarget(bot.modelSelection.instanceId)?.driverKind,
  guestDriven: cloudGuestDriven,
  recipientMemberOwned: (bot) => memberOwnedInOrg(bot) && orgDeniesFull(bot),
  memberAutoRefused: (bot, previous, next) => memberAutoRefused(bot, previous, next),
  memberRoomTurnLevel: (level) => memberRoomTurnLevel(level, memberAutoApprovalAllowed(cfg.organization)),
});

/** A running turn's Sagax decisions read the conversation's saved level now
 * (omb #3627), never the copy frozen on directTurnBots at dispatch. */
const liveApprovalMode = createLiveApprovalMode({ store, turnLevel: approvalModeForTurn });

/** The teammate's own level for a thread of its own, before any delegation. */
function ownThreadLevel(target: BotRecord, threadId: string): ApprovalMode {
  return approvalModeForTurn(store.projectBotForTask(target.id, threadId) ?? target, false, threadId);
}

const DELEGATED_LEVEL_NAMES: Partial<Record<ApprovalMode, string>> = { edits: "Auto-accept edits", auto: "Approve for me", full: "Full access" };

/** Compatibility wrapper: callers that have no hand-off node still raise the
 * first hop when `from` itself is a Primary Bot. */
function applyDelegatedLevel(
  from: BotRecord,
  fromThreadId: string,
  target: BotRecord,
  threadId: string,
  fromNodeId?: string,
): void {
  delegatedLevel.apply(from, fromThreadId, fromNodeId, target, threadId);
}

/** A room member's level for one turn. Work a Primary Bot hands out in a room runs
 * at the Primary Bot's level for that turn: the room thread is shared, so the
 * level is not stored on it — it rides the handoff. */
function roomTurnApprovalMode(bot: BotRecord, threadId: string, orchestration?: GroupTurnOrchestration): ApprovalMode {
  const handoff = orchestration?.roomHandoffId ? coordinator.node(orchestration.roomHandoffId) : undefined;
  return delegatedLevel.roomTurn(bot, threadId, handoff?.parentId ? coordinator.node(handoff.parentId) : undefined);
}

/** Privileged approval-mode transitions are deliberately absent from the
 * loopback HTTP authority model: a bot with shell access can curl that
 * surface itself. Only Electron's private utility-process channel can deliver
 * this message. */


/** Profile URLs are app-owned references, not merely strings with a trusted
 * prefix. Resolve them before persistence so every accepted avatar can be
 * fetched immediately and a deleted/guessed attachment id cannot become a
 * dangling profile reference. */
const storedAvatarExists = (avatarUrl: string): boolean =>
  attachmentExists(avatarUrl.slice("/api/attachments/".length));

/** A bot with its open thread's newest page, for HTTP replies and a
 * member stream's first frame of it. With a viewer the page is the one that
 * person may read; without one it is the whole page, and the caller projects
 * it (projectBotTranscript) or the frame layer does. */
const publicBotQueuedMessages = () => queuedSteerSnapshot((botId, threadId) => Boolean(store.taskByThread(botId, threadId)));


/** Goal-orchestrator worker turns driven by enqueueGoalAssignment: system
 * instructions (not a visible room request), and host.run must not chain
 * on groupQueues behind the orchestrator that is polling it. */
const goalWorkerTurns = new Map<string, { systemInstructions: string; onClaimed: () => void; failureMessageId?: string }>();

// busyBotId names only the speaker that currently owns the provider process.
// A room turn is wider: it also includes async setup and every responder still
// queued behind that speaker. Keep that operation visible for its whole
// lifetime so polling clients cannot mistake a handoff for completion.
const groupTurnOperations = new Map<string, Set<GroupTurnOperation>>();
// Group threads: the fold needs to know who is talking. The turn engine
// records the active member here before dispatching its turn.
const groupSpeakers = new Map<string, { botId: string; name: string; color: string; since?: number }>();
const groupApprovalRequests = new Map<string, { messageId: string }>();



/** The central runtime fold uses this to hide a coordinator's private
 * decision envelope from both streaming UI and the durable transcript. */
type GroupGoalCoordinatorTurn = {
  token: symbol;
  turnId?: string;
  assistantItems: string[];
  /** A timed-out provider may still emit after the goal operation returns.
   * Keep swallowing that abandoned turn until its real completion arrives. */
  discard: boolean;
  cleanupTimer?: ReturnType<typeof setTimeout>;
};
const groupGoalCoordinatorTurns = new Map<string, Set<GroupGoalCoordinatorTurn>>();
const GROUP_GOAL_COORDINATOR_GUARD_MS = 5 * 60_000;

function addGroupGoalCoordinatorTurn(threadId: string, turn: GroupGoalCoordinatorTurn): void {
  const turns = groupGoalCoordinatorTurns.get(threadId) ?? new Set<GroupGoalCoordinatorTurn>();
  turns.add(turn);
  groupGoalCoordinatorTurns.set(threadId, turns);
}

function removeGroupGoalCoordinatorTurn(threadId: string, turn: GroupGoalCoordinatorTurn): void {
  if (turn.cleanupTimer) clearTimeout(turn.cleanupTimer);
  const turns = groupGoalCoordinatorTurns.get(threadId);
  turns?.delete(turn);
  if (turns?.size === 0) groupGoalCoordinatorTurns.delete(threadId);
}

function hasUnboundDiscardedGroupGoalTurn(threadId: string): boolean {
  return [...(groupGoalCoordinatorTurns.get(threadId) ?? [])]
    .some((turn) => turn.discard && !turn.turnId);
}

/** Match private coordinator output to one provider turn, never merely to a
 * reusable room thread. Most adapters emit turn.started before sendTurn
 * resolves, so the first stable event may bind an otherwise pending guard. */


// The public and Primary Bot room tools use the same synchronous validation and write.
// Keep authorization at each ingress; no internal caller gains public admin scope.


const channelTaskBlocked = (group: GroupRecord) =>
  groupIsWorking(group) ||
  store.groupTasks(group.id).some((task) =>
    store.messagesFor(task.threadId).some(
      (message) =>
        message.kind === "options" &&
        message.card?.requestId &&
        (!isPersistentQuestionCard(message.card) || runningTurnEngines.has(task.threadId)) &&
        !message.card.answered &&
        !message.card.dismissed && !message.card.expired,
    ),
  );

