/** Preview requests carry the selected conversation, not whichever thread
 * happens to be the bot's default. A query never grants lifecycle authority. */
function computerPreviewBot(botId: string, url: URL): BotRecord | null {
  const threadId = url.searchParams.get("threadId");
  if (!threadId) return store.bot(botId);
  const bot = store.projectBotForTask(botId, threadId);
  if (!bot) throw Object.assign(new Error("no such task"), { status: 404 });
  return directTurnBots.get(threadId) ?? bot;
}


/** Discovery is read-only. Starting or creating a configured computer is
 * deferred until a chat tool selects it and the old turn releases its tools.
 * A Cloud home lists only the places it has (cloud-home.ts), so a bot never
 * tells the person to set up this computer or a Local VM there. */


/** The engine that dispatched each live turn. A bot's settings may change
 * mid-turn; an interrupt or steer must reach the engine actually running. */
const runningTurnEngines = new Map<string, NonNullable<ReturnType<typeof registry.get>>>();
/** Engine memory guard (server/memory/engine-memory-guard.ts): bounds the finished
 * sessions kept warm, closes them under memory pressure, holds routine
 * starts at the critical mark, and makes engines the kernel's OOM victims
 * instead of the server. */
const memoryGuard = memoryGuardSettings();
const ROUTINE_MEMORY_WAIT_MS = 10 * 60_000;
function idleEngineTtl(driverKind: string | undefined): number {
  return sessionIdlePolicy(driverKind === "claudeAgent" ? "CLAUDE" : driverKind === "codex" ? "CODEX" : "ACP").idleMs;
}
const idleEngines = new IdleEnginePool({
  maxIdle: memoryGuard.maxIdle,
  ttlMs: sessionIdlePolicy("CLAUDE").idleMs,
  // a live call keeps its warm process between spoken turns
  exempt: (threadId) => Boolean(voiceCalls.active(threadId)),
  log: (line) => console.log(line)
});
const memoryWatch = new MemoryWatch({
  pool: idleEngines,
  intervalMs: memoryGuard.intervalMs,
  highRatio: memoryGuard.highRatio,
  criticalRatio: memoryGuard.criticalRatio,
  childOomScoreAdj: memoryGuard.childOomScoreAdj,
  liveEngines: () => runningTurnEngines.size
});
// The bots' browsers count too (server/browser/browser-lifecycle-cleanup.ts engineBrowsers).
memoryWatch.useBrowsers(engineBrowsers({
  threadBrowser: (threadId) => {
    const bot = store.botByThread(threadId);
    if (!bot || bot.browser === false || !builtInBrowserEnabled(cfg) || browserEngineAttachCdpUrl(cfg)) return null;
    const confidential = store.isConfidentialThread(threadId);
    const profile = effectiveBrowserProfile(bot.id, bot.browserProfile);
    if (!confidential && profile === MY_CHROME_PROFILE) return null;
    // A temporary or confidential browser is never created here, only looked up.
    const session = confidential ? confidentialBrowserSessions.get(threadId)
      : profile === "guest" ? temporaryBrowserSessions.get(bot.id) : currentBrowserSession(bot.id, profile, threadId);
    return { session, spec: session === undefined ? undefined : usedBrowserSessions.get(session) };
  },
  sessions: () => usedBrowserSessions,
  held: (session) => !turnResources.free(`browser:${session}`),
  closeUnused: (session, spec) => browserRuntime.closeUnused(session, spec)
}));
memoryWatch.start();
function runningTurnInstance(bot: BotRecord | null | undefined, threadId: string): ReturnType<typeof registry.get> {
  // A turn always runs on the bot's own engine, wherever it works.
  return runningTurnEngines.get(threadId) ?? (bot ? registry.get(bot.modelSelection.instanceId) : null);
}

/** The engine takes pictures with a mid-turn steer (contracts:
 * capabilities.steerImages), as native input like a new turn's. */
function engineSteersImages(instance: ReturnType<typeof registry.get> | undefined): boolean {
  const capabilities = instance?.adapter.capabilities;
  return Boolean(capabilities?.queueing && capabilities.steerImages && capabilities.nativeImageInput && instance?.adapter.steer);
}


function claimBoatInventoryRequest(boxId: string): () => void {
  if (boatInventoryRequestsBusyIds.has(boxId)) {
    throw Object.assign(new Error("this cloud computer is being changed — wait for it to finish"), { status: 409 });
  }
  boatInventoryRequestsBusyIds.add(boxId);
  return () => boatInventoryRequestsBusyIds.delete(boxId);
}

/** Claim the owning bot synchronously after Boat revalidation and before the
 * provider mutation. startTurn checks the same set before doing any work, so
 * a new turn and an irreversible lifecycle action cannot pass each other. */

/** One synchronous lane for cloud lifecycle consumers. Both Settings and
 * bot-scoped actions use it, so whichever operation starts first excludes the
 * other instead of relying on a stale check made before a provider await.
 * Only opening an existing VPS viewer may coexist with its pending preview. */


function localVmTargetForBot(botId: string): LocalVmTarget {
  return localVmMode(cfg) === "per-bot" ? perBotLocalVmTarget(botId) : SHARED_LOCAL_VM_TARGET;
}

function localVmPoolSeatHolder(seat: number): LocalVmSeatHolder | null {
  return localVmLeases.forTarget(poolLocalVmTarget(seat).key).current(localVmOwnerBusy);
}

/** The Local VM a conversation's turn addresses. In pool mode each thread
 * draws a seat with TTL-bounded affinity so it reuses the desktop that
 * holds its login state; other modes are unchanged. */
function localVmTargetForThread(botId: string, threadId: string): LocalVmTarget {
  if (localVmMode(cfg) !== "pool") return localVmTargetForBot(botId);
  return poolLocalVmTarget(localVmSeatPool.assign(threadId, localVmPoolSeatHolder));
}

/** Best-effort seat for read-only surfaces (Computer panel previews,
 * screenshots, status payloads). Records no affinity: a status probe must
 * not steer a later turn onto a desktop its claim would not choose. */

function localVmLeaseFor(target: LocalVmTarget): LocalVmLease {
  return localVmLeases.forTarget(target.key);
}



// A running VM may have survived an app/server restart. Start its idle
// backstop even if nobody opens Settings or begins a turn this session. The
// bot's current destination is intentionally ignored: moving a bot to Cloud,
// Browser, This computer, Auto, or Off does not delete its old Local VM.
void (async () => {
  if (localVmMode(cfg) === "pool") {
    // Same restore rule as per-bot: idle shutdown preserves the container and
    // its provisioned workspace, so every surviving seat stays Auto-eligible.
    const seats = localVmMaxInstances(cfg);
    for (let seat = 0; seat < seats; seat += 1) {
      const target = poolLocalVmTarget(seat);
      if (localVmWorkspaceExists(target)) localVmSeen.add(target.key);
    }
    const runtime = await containerRuntimeStatus().catch(() => null);
    if (!runtime?.runtime || !runtime.daemonUp) return;
    const existing = await discoverExistingPoolLocalVms(seats, runtime.runtime).catch(() => []);
    const statuses = await Promise.all(existing.map((target) =>
      containerComputerStatus(undefined, undefined, target).catch(() => null),
    ));
    existing.forEach((target, index) => {
      noteLocalVmSeen(target, statuses[index]);
      if (shouldArmLocalVmIdle(statuses[index])) localVmIdleFor(target).touch();
    });
    return;
  }
  if (localVmMode(cfg) !== "per-bot") {
    const status = await containerComputerStatus(undefined, undefined, SHARED_LOCAL_VM_TARGET).catch(() => null);
    noteLocalVmSeen(SHARED_LOCAL_VM_TARGET, status);
    if (shouldArmLocalVmIdle(status)) localVmIdleFor(SHARED_LOCAL_VM_TARGET).touch();
    return;
  }
  // Idle cleanup removes the container, not its provisioned workspace. Restore
  // Auto eligibility before runtime discovery, including when it is offline.
  for (const bot of store.bots) {
    const target = perBotLocalVmTarget(bot.id);
    if (localVmWorkspaceExists(target)) localVmSeen.add(target.key);
  }
  const runtime = await containerRuntimeStatus().catch(() => null);
  if (!runtime?.runtime || !runtime.daemonUp) return;
  const existing = await discoverExistingPerBotLocalVms(store.bots, runtime.runtime).catch(() => []);
  const statuses = await Promise.all(existing.map(({ target }) =>
    containerComputerStatus(undefined, undefined, target).catch(() => null),
  ));
  existing.forEach(({ target }, index) => {
    noteLocalVmSeen(target, statuses[index]);
    if (shouldArmLocalVmIdle(statuses[index])) localVmIdleFor(target).touch();
  });
})().catch(() => {
  // Startup inspection is a backstop, not a reason to keep the app offline.
  // The Settings inventory remains available for a later explicit retry.
});

/** The desktop app's own server keeps its Local VM up by itself
 * (server/computer/local-vm-auto.ts): at launch, when a bot needs it, and after a
 * failure with a growing delay. Never on an organization server (the Local
 * VM there lives on each person's computer, electron/local-vm.mjs), a
 * Cloud home, or a self-hosted server without the desktop app. */
const localVmAuto = DESKTOP_MANAGED && IDENTITY.kind !== "perspicax" && !process.env.SAGAX_LOCAL_VM_TEST_NAMESPACE
  ? new LocalVmAutoStarter({
    mode: () => localVmMode(cfg),
    allowed: () => managedPolicy.computerAllowed("localVm") && !hostComputerRefusal(),
    status: () => containerComputerStatus(undefined, undefined, SHARED_LOCAL_VM_TARGET),
    startRuntime: (status) => startContainerRuntime(status.runtime),
    prepareImage: async () => {
      if (localVmImageBusy || localVmModeChangeBusy) throw new Error("another Local VM setup action is still running");
      localVmImageBusy = true;
      try { return await containerComputerAction("pull", undefined, undefined, SHARED_LOCAL_VM_TARGET); } finally { localVmImageBusy = false; }
    },
    create: () => localVmAutoLifecycle("run"),
    start: () => localVmAutoLifecycle("start"),
    remove: () => localVmAutoLifecycle("remove"),
    busy: () => localVmImageBusy || localVmModeChangeBusy || localVmLifecycleBusy.has(SHARED_LOCAL_VM_TARGET.key),
    wait: (ms) => new Promise((resolve) => setTimeout(resolve, ms)),
    now: () => Date.now(),
    schedule: (run, ms) => { const timer = setTimeout(run, ms); timer.unref?.(); return timer; },
    cancel: (handle) => clearTimeout(handle as NodeJS.Timeout),
    desktopWaitMs: LOCAL_VM_DESKTOP_WAIT_MS
  })
  : null;

/** One lifecycle step of the automatic start, with the same guards as the
 * Settings routes: never while a bot holds the desktop or a setup runs. */

// At launch: bring the Local VM up in the background.
if (localVmAuto) setTimeout(() => { void localVmAuto.ensure("launch").catch(reportBackgroundError); }, 3_000).unref?.();


