const duplexEpochByThread = new Map<string, ReturnType<typeof duplexEpoch>>();

/** startDuplexCallTurn's answer when the words join the running turn. */
const DUPLEX_JOIN_RUNNING_TURN = Symbol("duplex-join-running-turn");

/** A duplex call send: interrupt the in-flight turn if any, drop the
 * steer queue, start only this utterance. While the call turn runs a tool,
 * hands the words back to the caller's steer path instead. Never forks a
 * parallel task. */

/** Keep a person's words off the transcript until a direct-thread slot is
 * available. Reuse the existing cancellable, idempotent composer queue. */
/** Sends that arrived while a pre-warm of their thread was starting: the
 * first one takes the warm process; the others wait for it, so they queue
 * behind its turn instead of racing it into a 409 (server/threads/thread-prewarm.ts). */
const prewarmSends = new Map<string, Promise<unknown>>();
async function startOrQueueDirectMessage(...args: Parameters<typeof startOrQueueDirectMessageNow>) {
  const threadId = args[1];
  const ahead = prewarmSends.get(threadId);
  if (ahead) {
    await ahead.catch(reportBackgroundError);
    return startOrQueueDirectMessageNow(...args);
  }
  if (!threadPrewarm.has(threadId)) return startOrQueueDirectMessageNow(...args);
  const run = (async () => {
    await joinPrewarm(threadId);
    return startOrQueueDirectMessageNow(...args);
  })();
  prewarmSends.set(threadId, run);
  try {
    return await run;
  } finally {
    if (prewarmSends.get(threadId) === run) prewarmSends.delete(threadId);
  }
}

// ── parallel tasks (shared/parallel-tasks.ts, server/parallel-tasks.ts) ──
// A request sent while the conversation is busy can run as its own task: a
// thread of the same bot, linked to the conversation, whose first turn's
// result is posted back there as a reply to the request.

/** Parallel tasks stopped by a person before their result was posted. */
const parallelStops = new Set<string>();

/** The parallel task of a thread still owed a result, with its bot. */
function pendingParallelTask(threadId: string): { bot: BotRecord; task: TaskRecord } | null {
  const bot = store.botByThread(threadId);
  const task = bot ? store.taskByThread(bot.id, threadId) : undefined;
  return bot && task && parallelPending(task) ? { bot, task } : null;
}

/** A waiting parallel task holds its slot until its person has one free. */
function parallelTaskBlocked(botId: string, threadId: string): boolean {
  const task = store.taskByThread(botId, threadId);
  if (!task?.parallelOf) return false;
  return parallelBlocked({ task, tasks: store.tasks(botId), limit: botMaxParallelPerPerson(store.bot(botId), cfg), busy: (id) => threadBusy(botId, id) });
}

function patchParallelCard(parentThreadId: string, cardId: string | undefined, patch: Partial<ParallelTaskRef>) {
  if (!cardId) return;
  const card = store.messagesFor(parentThreadId).find((message) => message.id === cardId);
  if (!card?.parallelTask) return;
  store.patchMessage(parentThreadId, cardId, { parallelTask: { ...card.parallelTask, ...patch } });
}

/** The conversation a call hands work off from (server/voice/voice-turn.ts): its
 * summary and latest turns, as a written turn would rebuild them. */

/** Start (or queue) a parallel task for `text`, asked in `threadId`. */

// ── auto routing of a send while the bot works (server/busy-routing.ts) ──

/** What an auto send carried, kept with its routing handle. */
interface AutoRouteContext {
  replyTo?: Message;
  sendId?: string;
  sender?: ResolvedSender;
  trigger?: UsageTrigger;
  speaker?: TurnSpeaker;
  principalId?: string;
  auth?: RequestAuth;
}

const routableSteers = new RoutableSteers<AutoRouteContext>();

/** A conversation whose busy sends the bot may route: a bot's 1:1 thread
 * that is not itself a parallel task (a task of a task is refused), a
 * routine run or a room. Otherwise auto reads as joining the running turn. */
function autoRoutableThread(botId: string, threadId: string): boolean {
  const task = store.taskByThread(botId, threadId);
  return Boolean(task && !task.parallelOf && !task.routineRunId && !store.groupByThread(threadId));
}

/** The running work, in the person's words: the latest request of the
 * thread's active path (what the classifier compares a new message with). */
function runningRequestText(threadId: string): string {
  const asked = store.activePath(threadId).filter((message) => message.role === "user" && message.kind === "text" && message.text?.trim() && !message.parallelTask);
  return asked.slice(-2).map((message) => message.text!).join("\n");
}

/** The bot's tool-free one-shot for the fallback classification, under the
 * same gates as a segment digest (policy, budget, hosted models). */

/** route_message: the bot moves a message steered into its running turn.
 * `parallel` makes the person's row the request of a new parallel task;
 * `after` keeps the row and starts a turn on it once this one is done (the
 * tool's answer asks the bot to say so in one line). Idempotent per handle. Only the turn the words were
 * steered into may route them. */

/** A parallel task's first turn settled: post its result into the
 * conversation it answers, as a reply to the request, once. */

/** A turn that settled without turn.completed (refused before it ran, for
 * one) leaves its parallel task owed a result: settle it as not finished. */

/** Stop one parallel task: its running turn, or its place in line. */

/** After a restart: a parallel task whose turn was cut off and is not
 * waiting in line will never settle on its own. */

/** What a person's direct message became: a line in the transcript (a new
 * turn, or words steered into the running one), or a place in the queue. */


/** Refusal from acceptDirectSend: the route turns it into its HTTP answer. */
class DirectSendRefused extends Error {
  readonly status: number;
  readonly body: Record<string, unknown>;
  constructor(status: number, body: Record<string, unknown>) {
    super(typeof body.error === "string" ? body.error : "send refused");
    this.status = status;
    this.body = body;
  }
}

/** The refusals a direct send meets before it is sequenced, or null. */

/** `security.triage` for the person a turn acts for. The operator at this
 * computer holds it. A service, a guest and a member without the permission
 * do not. An organization admin holds every key. */
function misuseActor(principalId: string | undefined | null, origin?: string): { triage: boolean; principalId?: string } {
  const id = principalId?.trim() || undefined;
  const triage = origin === "operator" || (id ? can(principalPermissions(id), "security.triage") : false);
  return { triage, ...(id ? { principalId: id } : {}) };
}


/** The turn's person, including a solo operator, for the safety review. */
function safetyPrincipal(threadId: string): { principalId?: string; triage: boolean } {
  const speaker = turnSpeakers.get(threadId);
  const fromSpeaker = speaker && "principalId" in speaker ? speaker.principalId : undefined;
  const principalId = turnSpeakerPrincipals.get(threadId) ?? fromSpeaker;
  return misuseActor(principalId, speaker?.origin);
}

/** Isolated reviewer for one bot. It may only tighten a verdict, and only
 * the tool path awaits it. Shadow never calls it. */

/** 2026-10-21 (the reference design parity A1): the model reviewer of custom rules
 * (server/rules/custom-rules-model.ts). It answers a card like the person would,
 * through the engine that asked, and says so on the card and in the
 * decision log (`source: auto-review`, the rule, the reason). */
const customRulesModel = createCustomRulesModelReviewer({
  reviewer: (botId) => safetyReviewer(botId),
  stillOpen: (threadId, requestId) => {
    const card = store.messagesFor(threadId).find((row) => row.card?.requestId === requestId)?.card;
    return Boolean(card && !card.answered && !card.dismissed && !card.expired);
  },
  deliver: async (card, behavior, message) => {
    // the engine that asked, like every other answer given at request.opened
    const instance = registry.get(card.instanceId) ?? runningTurnEngines.get(card.threadId);
    if (!instance) return false;
    try {
      const outcome = await instance.adapter.respondToRequest(card.threadId, card.requestId, { behavior, ...(message ? { message } : {}) });
      if (behavior === "allow" && outcome === "rejected") {
        store.appendMessage(card.threadId, { role: "bot", kind: "activity", tool: { name: "The provider rejected this action despite your rule (automatic review).", ok: false } });
      }
      return behavior === "allow" ? outcome === "allowed-once" : outcome === "rejected" || outcome === "allowed-once";
    } catch {
      return false;
    }
  },
  settle: (card, verdict, notice) => {
    const row = store.messagesFor(card.threadId).find((candidate) => candidate.card?.requestId === card.requestId);
    if (row?.card) {
      const { reviewing: _reviewing, ...kept } = row.card;
      store.patchMessage(card.threadId, row.id, {
        card: {
          ...kept,
          customRule: notice,
          ...(verdict.kind === "ask" ? {} : { answeredBy: { kind: "worker" as const, via: "auto-review" as const } })
        }
      });
    }
    if (verdict.kind === "ask") return;
    const bot = store.bot(card.botId);
    appendDecision(DATA_DIR, {
      threadId: card.threadId, requestId: card.requestId, botId: card.botId, ...(bot ? { botName: bot.name } : {}),
      tool: card.call.tool, ...(card.call.summary ? { summary: card.call.summary } : {}),
      decision: verdict.kind === "allow" ? "auto-approved" : "auto-denied", source: "auto-review",
      ...(verdict.rule ? { rule: verdict.rule.id } : {}), ...(verdict.reason ? { reason: verdict.reason } : {})
    });
  }
});

setMisuseAlert((alert) => {
  const bot = alert.botId ? store.bot(alert.botId) : undefined;
  broadcast({
    kind: "notify",
    notification: {
      kind: "admin-action",
      botId: alert.botId ?? "",
      botName: bot?.name ?? "Sagax",
      threadId: alert.threadId ?? bot?.threadId ?? "",
      title: "Demande refusée",
      body: alert.message
    }
  }, { adminOnly: true });
});

// 2026-10-27 (#1098): the person's own folders on the server, for the misuse
// classifier and the safety review: their own bot's workspace and task
// folders, their own principal folder, and the attachment store whose tags
// the app writes into a message. Another bot's or person's folder stays a
// platform path.
setMisuseOwnPaths(({ principalId, botId }) => {
  const person = principalId?.trim() || (IDENTITY.kind === "perspicax" ? "" : localPrincipalId());
  const roots: string[] = [];
  const bot = botId ? store.bot(botId) : undefined;
  if (bot && person && samePerson(effectiveBotOwner(bot), person)) roots.push(workspaceDir(bot.id), join(TASK_WORKSPACES_DIR, bot.id));
  if (person && isPrincipalId(person)) roots.push(join(DATA_DIR, "principals", person));
  let real = DATA_DIR;
  try { real = realpathSync(DATA_DIR); } catch { /* not created yet */ }
  const spelled = roots.flatMap((root) => (real !== DATA_DIR && root.startsWith(`${DATA_DIR}/`) ? [root, real + root.slice(DATA_DIR.length)] : [root]));
  return { roots: spelled, attachmentsDir: ATTACHMENTS_DIR };
});

/** 2026-11-02: the server's data folder and this bot's workspace, as
 * written and through a linked data folder, for a prompt that must name no
 * path of the server (server/server-path-prompt.ts). */
function serverPathView(...args: any[]) {
  return (_serverPathViewImpl ??= createServerPathView(getLeafHost) as any)(...args);
}

/** 2026-11-02: this bot's own folders on the Sagax server (its workspace
 * and its task workspaces), as written and through a linked data folder.
 * A tool of the server environment given one answers where the bot's
 * folder in the environment is (server/sandbox/sandbox-server-path.ts). */
function serverBotRoots(botId: string): string[] {
  if (!/^[A-Za-z0-9_-]{1,128}$/.test(botId)) return [];
  const roots = [workspaceDir(botId), join(TASK_WORKSPACES_DIR, botId)];
  let real = DATA_DIR;
  try { real = realpathSync(DATA_DIR); } catch { /* not created yet */ }
  return roots.flatMap((root) => (real !== DATA_DIR && root.startsWith(`${DATA_DIR}/`) ? [root, real + root.slice(DATA_DIR.length)] : [root]));
}

// A risky call the engine will not ask about itself (a sandbox tool, a
// desktop tool) waits on this card. Auto does not answer it. The respond
// route settles it before any provider sees the request id.
setSafetyConfirm((request) => confirmHeldCard(request));
// #1905 (2026-11-02): every safety review that names its bot and thread
// reads the turn's Full access from the one decision (full-access-gate.ts),
// so a send, a destructive git operation or an unknown tool is never held
