      const principalId = turnMediaPrincipal(capability.threadId) ?? (IDENTITY.kind !== "perspicax" ? localPrincipalId() ?? "solo" : null);
      return principalId ? { botId: capability.botId, threadId: capability.threadId, principalId } : null;
