function auditValue(value: unknown): unknown {
  const whole = JSON.stringify(value) ?? "null";
  return whole.length <= 2_000 ? value : `${whole.length} characters, sha256 ${createHash("sha256").update(whole).digest("hex").slice(0, 16)}`;
}
